/** Replies generated by a terminal while painting a saved screen are not a
 * person's input and must never start a sleeping engine. */
export function isTerminalReport(data: string): boolean {
  return /^(?:\x1b\[(?:[?>=]?[0-9;:]*[cn]|[0-9]+;[0-9]+R|\?[0-9;]*u|[IO])|\x1b\](?:4|10|11);[^\x07]*(?:\x07|\x1b\\))$/.test(data);
}
